     1→import { useState, useEffect, useCallback, useRef } from 'react';
     2→import { useParams, Link } from 'react-router-dom';
     3→import { apiFetch } from '../services/api';
     4→import { getSocket } from '../services/socket';
     5→import LandMode from '../components/LandMode';
     6→import BundMode from '../components/BundMode';
     7→import RunningTotals from '../components/RunningTotals';
     8→
     9→interface Stats {
    10→  totalParticipants: number;
    11→  totalReports: number;
    12→  perRepeater: { short_name: string; count: number }[];
    13→}
    14→
    15→export default function ExercisePage() {
    16→  const { id } = useParams<{ id: string }>();
    17→  const [exercise, setExercise] = useState<any>(null);
    18→  const [mode, setMode] = useState<'land' | 'bund'>('land');
    19→  const oeLinkEnabled = exercise?.oe_link_enabled !== 0;
    20→  const [stats, setStats] = useState<Stats>({ totalParticipants: 0, totalReports: 0, perRepeater: [] });
    21→  const [reports, setReports] = useState<any[]>([]);
    22→  const [loading, setLoading] = useState(true);
    23→  const [organisator, setOrganisator] = useState('');
    24→  const socketRef = useRef(getSocket());
    25→
    26→  const refreshStats = useCallback(async () => {
    27→    if (!id) return;
    28→    try {
    29→      const s = await apiFetch(`/api/v1/exercises/${id}/stats`);
    30→      setStats(s);
    31→    } catch {}
    32→  }, [id]);
    33→
    34→  useEffect(() => {
    35→    if (!id) return;
    36→    setLoading(true);
    37→    apiFetch(`/api/v1/exercises/${id}`)
    38→      .then(data => {
    39→        setExercise(data);
    40→        setReports(data.reports || []);
    41→        if (data.organisator) setOrganisator(data.organisator);
    42→      })
    43→      .catch(() => {})
    44→      .finally(() => setLoading(false));
    45→    refreshStats();
    46→  }, [id, refreshStats]);
    47→
    48→  useEffect(() => {
    49→    if (!id) return;
    50→    const socket = socketRef.current;
    51→    socket.emit('join_exercise', { exercise_id: id });
    52→
    53→    socket.on('report_created', (data: any) => {
    54→      setReports(prev => [data, ...prev]);
    55→      refreshStats();
    56→    });
    57→    socket.on('report_updated', (data: any) => {
    58→      setReports(prev => prev.map(r => r.id === data.id ? data : r));
    59→      refreshStats();
    60→    });
    61→    socket.on('report_deleted', (data: any) => {
    62→      setReports(prev => prev.filter(r => r.id !== data.report_id));
    63→      refreshStats();
    64→    });
    65→
    66→    return () => {
    67→      socket.emit('leave_exercise', { exercise_id: id });
    68→      socket.off('report_created');
    69→      socket.off('report_updated');
    70→      socket.off('report_deleted');
    71→    };
    72→  }, [id, refreshStats]);
    73→
    74→  const handleReportCreated = useCallback((report: any) => {
    75→    setReports(prev => [report, ...prev]);
    76→    socketRef.current.emit('report_created', { ...report, exercise_id: id! });
    77→    refreshStats();
    78→  }, [id, refreshStats]);
    79→
    80→  const handleReportUpdated = useCallback((report: any) => {
    81→    setReports(prev => prev.map(r => r.id === report.id ? report : r));
    82→    socketRef.current.emit('report_updated', { ...report, exercise_id: id! });
    83→    refreshStats();
    84→  }, [id, refreshStats]);
    85→
    86→  const handleReportDeleted = useCallback((reportId: number) => {
    87→    setReports(prev => prev.filter(r => r.id !== reportId));
    88→    socketRef.current.emit('report_deleted', { report_id: reportId, exercise_id: id! });
    89→    refreshStats();
    90→  }, [id, refreshStats]);
    91→
    92→  const updateOrganisator = async (val: string) => {
    93→    await apiFetch(`/api/v1/exercises/${id}`, {
    94→      method: 'PATCH',
    95→      body: JSON.stringify({ organisator: val || null }),
    96→    });
    97→    setExercise((prev: any) => prev ? { ...prev, organisator: val || null } : null);
    98→  };
    99→
   100→  if (loading) return <p className="text-gray-500 p-4">Laden...</p>;
   101→  if (!exercise) return <p className="text-red-500 p-4">Übung nicht gefunden</p>;
   102→
   103→  return (
   104→    <div className="space-y-4">
   105→      <div className="flex items-center justify-between flex-wrap gap-2">
   106→        <h1 className="text-base sm:text-xl font-bold text-[#1e3a5f] min-w-0">
   107→          <span className="block sm:inline">{exercise.name || 'Übung'}</span>
   108→          <span className="hidden sm:inline"> — </span>
   109→          <span className="block sm:inline text-sm sm:text-xl">{new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit', year: 'numeric' })}</span>
   110→        </h1>
   111→        <div className="flex items-center gap-2 flex-wrap">
   112→          <div className="flex items-center gap-1.5">
   113→            <label className={`text-xs ${organisator ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>Organisator:</label>
   114→            <input
   115→              type="text"
   116→              value={organisator}
   117→              onChange={e => setOrganisator(e.target.value.toUpperCase())}
   118→              onBlur={e => updateOrganisator(e.target.value.toUpperCase())}
   119→              placeholder="Rufzeichen"
   120→              className={`border rounded px-2 py-1 text-sm font-mono uppercase w-24 sm:w-28 focus:outline-none focus:ring-2 focus:ring-blue-500 ${organisator ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
   121→            />
   122→          </div>
   123→          <Link to={`/exercises/${id}/setup`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-2 sm:px-3 py-1 rounded text-xs sm:text-sm">
   124→            Einrichten
   125→          </Link>
   126→          <Link to={`/exercises/${id}/reports`} className="bg-red-100 hover:bg-red-200 text-red-800 px-2 sm:px-3 py-1 rounded text-xs sm:text-sm">
   127→            Auswertung
   128→          </Link>
   129→        </div>
   130→      </div>
   131→
