   263→                                    <input value={editForm.notes} onChange={e => setEditForm({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-20" />
   264→                                    <button onClick={handleUpdate} className="text-green-600 text-xs font-bold">OK</button>
   265→                                    <button onClick={() => setEditingId(null)} className="text-gray-400 text-xs">X</button>
   266→                                  </div>
   267→                                </td>
   268→                              ) : (
   269→                                <>
   270→                                  <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   271→                                  <td className="py-0.5 font-mono font-medium cursor-pointer" onClick={() => handleEdit(r)}>{r.callsign}</td>
   272→                                  <td className="py-0.5 font-mono text-gray-500 w-24 cursor-pointer" onClick={() => handleEdit(r)}>
   273→                                    {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   274→                                  </td>
   275→                                  <td className="py-0.5 text-gray-500 cursor-pointer" onClick={() => handleEdit(r)}>{r.notes || ''}</td>
   276→                                  <td className="py-0.5 w-4">
   277→                                    <button onClick={() => handleDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   278→                                  </td>
   279→                                </>
   280→                              )}
   281→                            </tr>
   282→                          ))}
   283→                        </tbody>
   284→                      </table>
   285→                    </div>
   286→                  );
   287→                })()}
   288→              </>
   289→            ) : (
   290→              /* No Bezirke — flat list with input form */
   291→              <FlatReportRow
   292→                reports={repReports}
   293→                repeaterId={rep.repeater_id}
   294→                onSubmit={(form) => handleBezirkSubmit('', rep.repeater_id, form)}
   295→                onEdit={handleEdit}
