   219→              </div>
   220→              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
   221→                <button
   222→                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
   223→                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
   224→                >
   225→                  + Umsetzer
   226→                </button>
   227→                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
   228→                <input
   229→                  type="text"
   230→                  value={blOpCallsigns[bl.code] || ''}
   231→                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
   232→                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
   233→                  placeholder="Rufz."
   234→                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
   235→                />
   236→              </div>
   237→            </div>
   238→
   239→            {!isCollapsed && (
   240→              <div>
   241→                {addRepBl === bl.code && (
   242→                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
   243→                    <input
   244→                      type="text"
   245→                      value={newRepName}
   246→                      onChange={e => setNewRepName(e.target.value)}
   247→                      placeholder="Name"
   248→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
   249→                      autoFocus
   250→                    />
   251→                    <input
   252→                      type="text"
   253→                      value={newRepFreq}
   254→                      onChange={e => setNewRepFreq(e.target.value)}
   255→                      placeholder="MHz"
   256→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   257→                    />
   258→                    <input
   259→                      type="text"
   260→                      value={newRepCallsign}
   261→                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
   262→                      placeholder="Rufz."
   263→                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
   264→                    />
   265→                    <button
   266→                      onClick={() => addRepeater(bl.code)}
   267→                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
   268→                    >
   269→                      OK
   270→                    </button>
   271→                    <button
   272→                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
   273→                      className="text-gray-400 hover:text-gray-600 text-xs"
   274→                    >
   275→                      Abbrechen
   276→                    </button>
   277→                  </div>
   278→                )}
   279→                <div className="divide-y divide-gray-100">
   280→                  {blBezirke.map(bz => {
   281→                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
   282→                    return (
   283→                      <BezirkRow
   284→                        key={bz.code}
   285→                        bezirk={bz}
   286→                        reports={bzReports}
   287→                        linkedRepeaters={linkedRepeaters}
   288→                        defaultRepeaterId={defaultRepId}
   289→                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
   290→                        onEdit={handleEdit}
   291→                        onDelete={handleDelete}
   292→                        editingId={editingId}
   293→                        editForm={editForm}
   294→                        onEditChange={setEditForm}
   295→                        onEditSave={handleUpdate}
   296→                        onEditCancel={() => setEditingId(null)}
   297→                      />
   298→                    );
   299→                  })}
   300→                  {/* Reports without matching bezirk — shown directly as list items */}
   301→                  {(() => {
   302→                    const bzCodes = new Set(blBezirke.map(b => b.code));
   303→                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
   304→                    if (unassigned.length === 0) return null;
   305→                    return (
   306→                      <div className="px-3 py-1.5">
   307→                        <table className="w-full text-xs mb-1">
   308→                          <tbody>
   309→                            {unassigned.map((r, idx) => (
   310→                              <tr key={r.id} className="hover:bg-blue-50 group">
   311→                                {editingId === r.id ? (
   312→                                  <td colSpan={5} className="py-0.5">
   313→                                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1">
   314→                                      <span className="font-mono font-medium">{r.callsign}</span>
   315→                                      <input value={editForm.rapport} onChange={e => setEditForm({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-20" autoFocus />
   316→                                      <input value={editForm.notes} onChange={e => setEditForm({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-20" />
   317→                                      <button onClick={handleUpdate} className="text-green-600 text-xs font-bold">OK</button>
   318→                                      <button onClick={() => setEditingId(null)} className="text-gray-400 text-xs">X</button>
   319→                                    </div>
   320→                                  </td>
   321→                                ) : (
   322→                                  <>
   323→                                    <td className="py-0.5 text-gray-400 w-4">{idx + 1}</td>
   324→                                    <td className="py-0.5 font-mono font-medium cursor-pointer" onClick={() => handleEdit(r)}>{r.callsign}</td>
   325→                                    <td className="py-0.5 font-mono text-gray-500 w-24 cursor-pointer" onClick={() => handleEdit(r)}>
   326→                                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   327→                                    </td>
   328→                                    <td className="py-0.5 text-gray-500 cursor-pointer" onClick={() => handleEdit(r)}>{r.notes || ''}</td>
   329→                                    <td className="py-0.5 w-4">
   330→                                      <button onClick={() => handleDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   331→                                    </td>
   332→                                  </>
   333→                                )}
   334→                              </tr>
   335→                            ))}
   336→                          </tbody>
   337→                        </table>
   338→                      </div>
   339→                    );
   340→                  })()}
   341→                </div>
   342→              </div>
   343→            )}
   344→          </div>
   345→        );
   346→      })}
   347→    </div>
   348→  );
   349→}
