const Database = require('better-sqlite3');
const db = new Database('/data/bosarsalog.db');

// Find all bad operators and their reports
const badOps = db.prepare('SELECT id, callsign FROM operators WHERE length(callsign) > 20').all();
console.log('Bad operators found:', badOps.length);
for (const op of badOps) {
  console.log('  ID:', op.id, '- starts with:', op.callsign.substring(0, 60));
  // Check reports
  const reports = db.prepare('SELECT id FROM signal_reports WHERE operator_id = ?').all(op.id);
  console.log('    Reports:', reports.length);
  // Delete reports first
  if (reports.length > 0) {
    db.prepare('DELETE FROM signal_reports WHERE operator_id = ?').run(op.id);
    console.log('    Deleted reports');
  }
  // Delete attendance
  db.prepare('DELETE FROM exercise_attendance WHERE operator_id = ?').run(op.id);
  // Delete operator
  db.prepare('DELETE FROM operators WHERE id = ?').run(op.id);
  console.log('    Deleted operator');
}
console.log('\\nCleanup done.');
