input.contents:
const XLSX = require('xlsx');
const path = require('path');

const filePath = '/home/achildrenmile/Downloads/2026 BOS-ARSA - Krisenkommunikationsübung.xlsx';
const wb = XLSX.readFile(filePath, { cellStyles: true, cellNF: true, cellDates: true });

console.log('='.repeat(80));
console.log('WORKBOOK ANALYSIS');
console.log('='.repeat(80));
console.log(`\nFile: ${path.basename(filePath)}`);
console.log(`Total sheets: ${wb.SheetNames.length}`);
console.log(`\nSheet names:`);
wb.SheetNames.forEach((name, i) => console.log(`  ${i + 1}. "${name}"`));

console.log('\n' + '='.repeat(80));
console.log('SHEET-BY-SHEET OVERVIEW');
console.log('='.repeat(80));

wb.SheetNames.forEach((name, idx) => {
  const ws = wb.Sheets[name];
  const ref = ws['!ref'];
  const merges = ws['!merges'] || [];

  console.log(`\n${'─'.repeat(80)}`);
  console.log(`SHEET ${idx + 1}: "${name}"`);
  console.log(`${'─'.repeat(80)}`);
  console.log(`  Range: ${ref || 'EMPTY'}`);
  console.log(`  Merged cells: ${merges.length}`);

  if (merges.length > 0 && merges.length <= 50) {
    console.log(`  Merge details:`);
    merges.forEach(m => {
      const startCell = XLSX.utils.encode_cell(m.s);
      const endCell = XLSX.utils.encode_cell(m.e);
      const val = ws[startCell] ? ws[startCell].v : '(empty)';
      console.log(`    ${startCell}:${endCell} = "${val}"`);
    });
  } else if (merges.length > 50) {
    console.log(`  First 30 merges:`);
    merges.slice(0, 30).forEach(m => {
      const startCell = XLSX.utils.encode_cell(m.s);
      const endCell = XLSX.utils.encode_cell(m.e);
      const val = ws[startCell] ? ws[startCell].v : '(empty)';
      console.log(`    ${startCell}:${endCell} = "${val}"`);
    });
    console.log(`    ... and ${merges.length - 30} more merges`);
  }

  if (!ref) return;

  const range = XLSX.utils.decode_range(ref);
  const numRows = range.e.r - range.s.r + 1;
  const numCols = range.e.c - range.s.c + 1;
  console.log(`  Dimensions: ${numRows} rows x ${numCols} cols`);

  // Show first 5 rows with raw cell values
  console.log(`\n  First 5 rows (raw):`);
  const maxRow = Math.min(range.s.r + 4, range.e.r);
  for (let r = range.s.r; r <= maxRow; r++) {
    const rowData = [];
    for (let c = range.s.c; c <= Math.min(range.e.c, 25); c++) {
      const addr = XLSX.utils.encode_cell({ r, c });
      const cell = ws[addr];
      if (cell) {
        rowData.push(`${XLSX.utils.encode_col(c)}=${JSON.stringify(cell.v)}`);
      }
    }
