nix-shell -p nodejs --run 'node -e "
const XLSX = require(\"xlsx\");
const wb = XLSX.readFile(\"/tmp/bosarsa2.xlsx\");

const allReports = [];
const allAbbreviations = new Set();
const rstFormats = new Set();

for (const name of wb.SheetNames) {
  if (!name.startsWith(\"202\")) continue;
  const ws = wb.Sheets[name];
  const data = XLSX.utils.sheet_to_json(ws, { header: 1, defval: \"\" });

  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    if (!row || !row[0]) continue;
    const attended = row[3] && parseInt(String(row[3])) > 0;
    if (!attended) continue;

    for (let c = 15; c <= 25; c++) {
      let val = row[c] ? String(row[c]).trim() : \"\";
      if (!val || val === \"0\") continue;
      allReports.push(val);

      // Try parse RST
      const isOp = val.toUpperCase().startsWith(\"OP\");
      const cleaned = val.replace(/^OP\\s*/i, \"\").trim();

      // Match R/S pattern
      const m = cleaned.match(/^(\\d)\\/(\\d)(\\+{1,2}|\\+\\d+)?\\s*(.*)/);
      if (m) {
        const [, r, s, db, suffix] = m;
        const sfx = suffix ? suffix.trim() : \"\";
        if (sfx) allAbbreviations.add(sfx);
        rstFormats.add((isOp ? \"OP \" : \"\") + \"R/S\" + (db || \"\") + (sfx ? \" +suffix\" : \"\"));
      } else if (!isOp || cleaned) {
        rstFormats.add(val.substring(0, 30));
      }
    }
  }
}

console.log(\"Total report cells across all sheets: \" + allReports.length);
console.log(\"\\n=== RST formats found ===\");
[...rstFormats].sort().forEach(f => console.log(\"  \" + f));
console.log(\"\\n=== Location abbreviations found ===\");
[...allAbbreviations].sort().forEach(a => console.log(\"  \" + a));
"' 2>&1

