const Database = require('better-sqlite3');
const fs = require('fs');

const records = JSON.parse(fs.readFileSync('/tmp/rufzeichen.json', 'utf-8'));
console.log('Records to import:', records.length);

const PREFIX_MAP = [
  [/^OE1/, '01'], [/^OE2/, '02'], [/^OE3/, '03'], [/^OE4/, '04'], [/^OE5/, '05'],
  [/^OE6/, '06'], [/^OE7/, '07'], [/^OE8/, '08'], [/^OE9/, '09'],
];
function toBlCode(cs) {
  for (const [re, code] of PREFIX_MAP) { if (re.test(cs)) return code; }
  return null;
}

const db = new Database('/data/bosarsalog.db');
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

const selectOp = db.prepare('SELECT id, name, qth FROM operators WHERE callsign = ?');
const insertOp = db.prepare("INSERT INTO operators (callsign, name, qth, bundesland_code, updated_at) VALUES (?, ?, ?, ?, datetime('now'))");
const updateOp = db.prepare("UPDATE operators SET name = ?, qth = ?, updated_at = datetime('now') WHERE callsign = ?");

let inserted = 0, updated = 0, skipped = 0;

const importAll = db.transaction(() => {
  for (const rec of records) {
    const existing = selectOp.get(rec.callsign);
    if (existing) {
      if (existing.name !== rec.name || existing.qth !== rec.qth) {
        updateOp.run(rec.name, rec.qth, rec.callsign);
        updated++;
      } else {
        skipped++;
      }
    } else {
      insertOp.run(rec.callsign, rec.name, rec.qth, toBlCode(rec.callsign));
      inserted++;
    }
  }
});
importAll();

console.log('Inserted:', inserted);
console.log('Updated:', updated);
console.log('Skipped:', skipped);
console.log('Total:', inserted + updated + skipped);
db.close();

