const Database = require('/app/node_modules/better-sqlite3');
const fs = require('fs');

const db = new Database('/data/bosarsalog.db');
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

// --- FIX 1: Remove exercise_repeaters with 0 reports ---
console.log('=== FIX 1: Remove unused exercise_repeaters ===');

const exercises = db.prepare("SELECT id, name FROM exercises WHERE name LIKE 'Krisenkommunikations%'").all();

let removedTotal = 0;
for (const ex of exercises) {
  // Find repeaters linked to this exercise that have NO reports
  const unused = db.prepare(`
    SELECT er.exercise_id, er.repeater_id, r.short_name, r.site_name
    FROM exercise_repeaters er
    JOIN repeaters r ON r.id = er.repeater_id
    WHERE er.exercise_id = ?
    AND NOT EXISTS (
      SELECT 1 FROM signal_reports sr
      WHERE sr.exercise_id = er.exercise_id AND sr.repeater_id = er.repeater_id
    )
  `).all(ex.id);

  if (unused.length > 0) {
    console.log(`\n${ex.name}:`);
    for (const u of unused) {
      console.log(`  Removing: ${u.short_name} (${u.site_name || 'direct'}) — 0 reports`);
      db.prepare('DELETE FROM exercise_repeaters WHERE exercise_id = ? AND repeater_id = ?').run(u.exercise_id, u.repeater_id);
      removedTotal++;
    }
  }
}
console.log(`\nRemoved ${removedTotal} unused exercise_repeater links`);

// Verify remaining
for (const ex of exercises) {
  const remaining = db.prepare(`
    SELECT r.short_name, COUNT(sr.id) as cnt
    FROM exercise_repeaters er
    JOIN repeaters r ON r.id = er.repeater_id
    LEFT JOIN signal_reports sr ON sr.exercise_id = er.exercise_id AND sr.repeater_id = er.repeater_id
    WHERE er.exercise_id = ?
    GROUP BY er.repeater_id
    ORDER BY cnt DESC
  `).all(ex.id);
  console.log(`\n${ex.name}: ${remaining.length} repeaters`);
  remaining.forEach(r => console.log(`  ${r.short_name}: ${r.cnt} reports`));
}

// --- FIX 2: Clear name/qth for operators NOT in Rufzeichen list ---
console.log('\n\n=== FIX 2: Clear data for non-Rufzeichen operators ===');

const rufzeichen = JSON.parse(fs.readFileSync('/tmp/rufzeichen.json', 'utf-8'));
const rufSet = new Set(rufzeichen.map(r => r.callsign));
console.log(`Rufzeichen list: ${rufSet.size} callsigns`);

// Get all operators
const allOps = db.prepare('SELECT id, callsign, name, qth, bundesland_code FROM operators').all();
let cleared = 0;

const clearStmt = db.prepare('UPDATE operators SET name = NULL, qth = NULL, bundesland_code = NULL WHERE id = ?');

const clearAll = db.transaction(() => {
  for (const op of allOps) {
    if (!rufSet.has(op.callsign)) {
      // Not in Rufzeichen list — clear name, qth, bundesland_code
      if (op.name || op.qth || op.bundesland_code) {
        clearStmt.run(op.id);
        console.log(`  Cleared: ${op.callsign} (was: name="${op.name}", qth="${op.qth}", bl=${op.bundesland_code})`);
        cleared++;
      }
    }
  }
});
clearAll();

console.log(`\nCleared ${cleared} operators not in Rufzeichen list`);
console.log('Total operators:', db.prepare('SELECT COUNT(*) as c FROM operators').get().c);
console.log('With name:', db.prepare('SELECT COUNT(*) as c FROM operators WHERE name IS NOT NULL').get().c);
console.log('Without name:', db.prepare('SELECT COUNT(*) as c FROM operators WHERE name IS NULL').get().c);

db.close();
console.log('\nDone!');

