const rufSet = new Set(rufzeichen.map(r => r.callsign));
console.log(`Rufzeichen list: ${rufSet.size} callsigns`);

// Get all operators
const allOps = db.prepare('SELECT id, callsign, name, qth, bundesland_code FROM operators').all();
let cleared = 0;

const clearStmt = db.prepare('UPDATE operators SET name = NULL, qth = NULL, bundesland_code = NULL WHERE id = ?');

const clearAll = db.transaction(() => {
  for (const op of allOps) {
    if (!rufSet.has(op.callsign)) {
      // Not in Rufzeichen list — clear name, qth, bundesland_code
      if (op.name || op.qth || op.bundesland_code) {
        clearStmt.run(op.id);
        console.log(`  Cleared: ${op.callsign} (was: name="${op.name}", qth="${op.qth}", bl=${op.bundesland_code})`);
        cleared++;
      }
    }
  }
});
clearAll();

console.log(`\nCleared ${cleared} operators not in Rufzeichen list`);
console.log('Total operators:', db.prepare('SELECT COUNT(*) as c FROM operators').get().c);
console.log('With name:', db.prepare('SELECT COUNT(*) as c FROM operators WHERE name IS NOT NULL').get().c);
console.log('Without name:', db.prepare('SELECT COUNT(*) as c FROM operators WHERE name IS NULL').get().c);

db.close();
console.log('\nDone!');

