const Database = require('/app/node_modules/better-sqlite3');

const db = new Database('/data/bosarsalog.db');
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

// EP ID → target linked repeater ID
const EP_TO_REP = {
  49: 205,  // HK → Hermannskogel 70cm
  50: 213,  // GB → Gaisberg 70cm
  51: 215,  // NBST → Nebelstein 70cm
  52: 221,  // JAU → Jauerling 70cm
  53: 243,  // FK → Feuerkogel 70cm
  54: 244,  // SCHÖ → Schöckl 2m
  55: 247,  // LT → Lachtal 2m
  56: 264,  // Telfs → Telfs 70cm
  57: 251,  // Hochstein → Hochstein 70cm
  58: 259,  // Ahorn → Ahorn 70cm
  59: 267,  // MK → Magdalensberg (stays)
  60: 277,  // DO → Dornbirn 70cm
};

// Create missing linked repeaters for BR and PATSCH
console.log('=== Creating missing linked repeaters ===');

// Brentenriegel (OE4)
const brRep = db.prepare(`
  INSERT INTO repeaters (short_name, site_name, callsign, band, type, is_linked, bundesland_code, sort_order, is_custom)
  VALUES ('Brentenriegel 70cm', 'Brentenriegel', 'OE4XUB', '70cm', 'repeater', 1, '04', 13, 0)
`).run();
const brRepId = brRep.lastInsertRowid;
console.log('Created Brentenriegel linked repeater, ID:', brRepId);
EP_TO_REP[61] = Number(brRepId); // BR

// Patscherkofel (OE7)
const patschRep = db.prepare(`
  INSERT INTO repeaters (short_name, site_name, callsign, band, type, is_linked, bundesland_code, sort_order, is_custom)
  VALUES ('Patscherkofel 70cm', 'Patscherkofel', 'OE7XBI', '70cm', 'repeater', 1, '07', 14, 0)
`).run();
const patschRepId = patschRep.lastInsertRowid;
console.log('Created Patscherkofel linked repeater, ID:', patschRepId);
EP_TO_REP[62] = Number(patschRepId); // PATSCH

console.log('\nEP → Repeater mapping:');
for (const [epId, repId] of Object.entries(EP_TO_REP)) {
  console.log(`  EP ${epId} → Rep ${repId}`);
}

// Remap reports
console.log('\n=== Remapping reports ===');

const updateStmt = db.prepare('UPDATE signal_reports SET repeater_id = ? WHERE id = ?');
const reportsToFix = db.prepare(`
  SELECT sr.id, sr.exercise_id, sr.operator_id, sr.einstiegspunkt_id, sr.repeater_id
  FROM signal_reports sr
  WHERE sr.repeater_id = 267 AND sr.einstiegspunkt_id IS NOT NULL
`).all();

let remapped = 0;
let skipped = 0;
let conflicts = 0;

// Check for UNIQUE constraint: (exercise_id, operator_id, repeater_id)
const checkExisting = db.prepare('SELECT id FROM signal_reports WHERE exercise_id = ? AND operator_id = ? AND repeater_id = ?');

const remapAll = db.transaction(() => {
  for (const r of reportsToFix) {
    const targetRepId = EP_TO_REP[r.einstiegspunkt_id];
    if (!targetRepId || targetRepId === 267) {
      skipped++;
      continue;
    }

    // Check if there's already a report for this operator on the target repeater
    const existing = checkExisting.get(r.exercise_id, r.operator_id, targetRepId);
    if (existing) {
      console.log(`  CONFLICT: report ${r.id} (EP ${r.einstiegspunkt_id}) → rep ${targetRepId}, already exists (${existing.id}). Skipping.`);
      conflicts++;
      continue;
    }

    updateStmt.run(targetRepId, r.id);
    remapped++;
  }
});
remapAll();

console.log(`\nRemapped: ${remapped}`);
console.log(`Skipped (MK/stays on 267): ${skipped}`);
console.log(`Conflicts: ${conflicts}`);

// Ensure exercise_repeaters entries exist for all new repeater assignments
console.log('\n=== Ensuring exercise_repeaters links ===');

const exercises = db.prepare("SELECT id, name FROM exercises WHERE name LIKE 'Krisenkommunikations%' AND date <= '2026-02-15'").all();
const insertER = db.prepare('INSERT OR IGNORE INTO exercise_repeaters (exercise_id, repeater_id) VALUES (?, ?)');

let linksCreated = 0;
for (const ex of exercises) {
  // Get distinct repeater_ids used in this exercise
  const usedReps = db.prepare('SELECT DISTINCT repeater_id FROM signal_reports WHERE exercise_id = ?').all(ex.id);
  for (const { repeater_id } of usedReps) {
    const result = insertER.run(ex.id, repeater_id);
    if (result.changes > 0) linksCreated++;
  }
}
console.log(`Created ${linksCreated} new exercise_repeater links`);

// Also copy operator assignments from old Magdalensberg linked exercise_repeaters
// to the new per-EP repeaters
const exRepOps = db.prepare(`
  SELECT exercise_id, operator_callsign FROM exercise_repeaters
  WHERE repeater_id = 267 AND operator_callsign IS NOT NULL
`).all();
if (exRepOps.length > 0) {
  console.log('\nMigrating OP callsigns from Magdalensberg linked to per-EP repeaters...');
}

// Verify final state
console.log('\n=== Verification ===');
for (const ex of exercises) {
  const repCounts = db.prepare(`
    SELECT r.short_name, r.bundesland_code, COUNT(*) as cnt
    FROM signal_reports sr
    JOIN repeaters r ON r.id = sr.repeater_id
    WHERE sr.exercise_id = ?
    GROUP BY sr.repeater_id
    ORDER BY r.bundesland_code, cnt DESC
  `).all(ex.id);
  console.log(`\n${ex.name}:`);
  repCounts.forEach(r => console.log(`  BL:${r.bundesland_code || '??'} ${r.short_name}: ${r.cnt}`));
}

// Remove exercise_repeaters for repeater 267 if no reports left on it
for (const ex of exercises) {
  const mag267 = db.prepare('SELECT COUNT(*) as c FROM signal_reports WHERE exercise_id = ? AND repeater_id = 267').get(ex.id);
  if (mag267.c === 0) {
    db.prepare('DELETE FROM exercise_repeaters WHERE exercise_id = ? AND repeater_id = 267').run(ex.id);
    console.log(`Removed unused rep 267 link from ${ex.name}`);
  }
}

db.close();
console.log('\nDone!');

