const Database = require('/app/node_modules/better-sqlite3');
const crypto = require('crypto');
const db = new Database('/data/bosarsalog.db');
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

// Get all existing exercise dates
const existing = new Set(
  db.prepare("SELECT date FROM exercises").all().map(e => e.date)
);

// Generate all Sundays in 2026
const sundays = [];
const d = new Date('2026-01-04T00:00:00'); // first Sunday of 2026
while (d.getFullYear() === 2026) {
  const dateStr = d.toISOString().slice(0, 10);
  sundays.push(dateStr);
  d.setDate(d.getDate() + 7);
}

console.log('All Sundays in 2026:', sundays.length);
console.log('Existing exercises:', existing.size);

const toCreate = sundays.filter(s => !existing.has(s));
console.log('Missing Sundays:', toCreate.length);

const insert = db.prepare(`
  INSERT INTO exercises (id, name, date, oe_link_enabled, created_at, updated_at)
  VALUES (?, ?, ?, 1, datetime('now'), datetime('now'))
`);

const insertAll = db.transaction(() => {
  for (const date of toCreate) {
    const id = crypto.randomUUID();
    const name = 'Krisenkommunikationsübung ' + date;
    insert.run(id, name, date);
    console.log('  Created:', name);
  }
});
insertAll();

const total = db.prepare("SELECT COUNT(*) as c FROM exercises WHERE name LIKE 'Krisenkommunikations%'").get().c;
