const Database = require('/app/node_modules/better-sqlite3');
const fs = require('fs');

const db = new Database('/data/bosarsalog.db');
const importData = JSON.parse(fs.readFileSync('/tmp/bosarsa-import.json', 'utf-8'));

// For each exercise, compare parsed reports with DB reports
for (const ex of importData.exercises) {
  const dbEx = db.prepare("SELECT id FROM exercises WHERE date = ?").get(ex.date);
  if (!dbEx) continue;

  // Get all DB reports for this exercise
  const dbReports = db.prepare(`
    SELECT sr.*, o.callsign
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    WHERE sr.exercise_id = ?
  `).all(dbEx.id);

  // Build set of (callsign, repeater) in DB
  const dbSet = new Set();
  for (const r of dbReports) {
    dbSet.add(r.callsign + '|' + r.repeater_id);
  }

  // All repeater IDs used in DB for this exercise (including remapped ones)
  // We need to map original repeater IDs to potentially remapped ones
  // The import JSON has reports with repeaterId=267 for Magdalensberg linked
  // After remap, those are on different repeater IDs based on EP

  // Count parsed reports
  let parsedCount = 0;
  let inDb = 0;
  let missing = [];

  for (const att of ex.attendees) {
    for (const rep of att.reports) {
      parsedCount++;
      // Check if this report exists in DB
      // The repeater might have been remapped from 267 to a linked repeater
      const found = dbReports.find(r =>
        r.callsign === att.callsign &&
        (r.repeater_id === rep.repeaterId ||
         // Check remapped: original was 267, now could be any linked repeater
         (rep.repeaterId === 267 && r.einstiegspunkt_id === rep.einstiegspunktId))
      );
      if (found) {
        inDb++;
      } else {
        missing.push({
          callsign: att.callsign,
          repeaterId: rep.repeaterId,
          epId: rep.einstiegspunktId,
          isOp: rep.isOp,
          readability: rep.readability,
          strength: rep.strength,
          dbOverS9: rep.dbOverS9,
          original: rep.original,
        });
      }
    }
  }

  const diff = parsedCount - dbReports.length;
  if (diff !== 0 || missing.length > 0) {
    console.log(`\n=== ${ex.date} ===`);
    console.log(`Parsed: ${parsedCount} | DB: ${dbReports.length} | Diff: ${diff}`);
    if (missing.length > 0) {
      console.log(`Missing from DB (${missing.length}):`);
      missing.forEach(m => {
        console.log(`  ${m.callsign} | Rep: ${m.repeaterId} | EP: ${m.epId || '—'} | ${m.isOp ? 'OP ' : ''}${m.readability || ''}/${m.strength || ''}${m.dbOverS9 || ''} | "${m.original}"`);
      });
    }
  }
}

db.close();

