const EP_TO_REP = {
  49: 205, 50: 213, 51: 215, 52: 221, 53: 243, 54: 244, 55: 247,
  56: 264, 57: 251, 58: 259, 59: 267, 60: 277, 61: 285, 62: 286,
};

for (const ex of importData.exercises) {
  const dbEx = db.prepare("SELECT id FROM exercises WHERE date = ?").get(ex.date);
  if (!dbEx) continue;

  const dbReports = db.prepare(`
    SELECT sr.*, o.callsign
    FROM signal_reports sr
    JOIN operators o ON o.id = sr.operator_id
    WHERE sr.exercise_id = ?
  `).all(dbEx.id);

  // Build lookup: callsign → list of reports
  const dbByCallsign = {};
  for (const r of dbReports) {
    if (!dbByCallsign[r.callsign]) dbByCallsign[r.callsign] = [];
    dbByCallsign[r.callsign].push(r);
  }

  let missing = [];

  for (const rep of ex.reports) {
    const callsign = rep.callsign;
    const origRepId = rep.repeaterId;
    const epId = rep.epId;

    // Determine expected repeater_id after remap
    let expectedRepId = origRepId;
    if (origRepId === 267 && epId && EP_TO_REP[epId]) {
      expectedRepId = EP_TO_REP[epId];
    }

    const dbReps = dbByCallsign[callsign] || [];
    const found = dbReps.find(r => r.repeater_id === expectedRepId);

    if (!found) {
      // Also check if it's in notes of another report (merged multi-EP)
      const inNotes = dbReps.find(r =>
        r.notes && r.notes.includes(rep.original)
      );
      if (!inNotes) {
        missing.push({
          callsign,
          repeaterId: origRepId,
          expectedRepId,
          epId,
          epAbbrev: rep.epAbbrev,
          isOp: rep.isOp,
          r: rep.readability,
          s: rep.strength,
          db: rep.dbOverS9,
          original: rep.original,
        });
      }
    }
  }

  console.log(`${ex.date} | Excel: ${ex.reports.length} | DB: ${dbReports.length} | Diff: ${dbReports.length - ex.reports.length} | Nicht gefunden: ${missing.length}`);
  if (missing.length > 0) {
    missing.forEach(m => {
      console.log(`  FEHLT: ${m.callsign} | Rep ${m.repeaterId}→${m.expectedRepId} | EP: ${m.epAbbrev || '—'} | ${m.isOp ? 'OP ' : ''}${m.r || ''}/${m.s || ''}${m.db || ''} | "${m.original}"`);
    });
  }
}

db.close();

