const fs = require('fs');
const db = new Database('/data/bosarsalog.db');
const importData = JSON.parse(fs.readFileSync('/tmp/bosarsa-import.json', 'utf-8'));

console.log('Datum       | Excel | DB  | Diff | Merged (Extra-QSOs im notes-Feld)');
console.log('------------|-------|-----|------|------------------------------------');

let totalExcel = 0, totalDb = 0, totalExtras = 0;

for (const ex of importData.exercises) {
  const dbEx = db.prepare('SELECT id FROM exercises WHERE date = ?').get(ex.date);
  const dbCount = db.prepare('SELECT COUNT(*) as c FROM signal_reports WHERE exercise_id = ?').get(dbEx.id).c;

  // Count duplicate (callsign, repeaterId) in JSON — these got merged
  const grouped = {};
  for (const rep of ex.reports) {
    const key = rep.callsign + '|' + rep.repeaterId;
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(rep);
  }

  let extras = 0;
  const mergeDetails = [];
  for (const [key, reps] of Object.entries(grouped)) {
    if (reps.length > 1) {
      extras += reps.length - 1;
      const cs = key.split('|')[0];
      mergeDetails.push(cs + ': ' + reps.map(r => '"' + r.original + '"').join(' + '));
    }
  }

  const diff = dbCount - ex.reports.length;
  totalExcel += ex.reports.length;
  totalDb += dbCount;
