  for (const d of mergeDetails) {
    console.log('            |       |     |      |   ' + d);
  }
}

console.log('------------|-------|-----|------|------------------------------------');
console.log('TOTAL       | ' + String(totalExcel).padStart(3) + '   | ' + String(totalDb).padStart(3) + ' | ' + String(totalDb - totalExcel).padStart(3) + '  | ' + totalExtras + ' merged');
