let XLSX;
try { XLSX = require('xlsx'); } catch (e) {
  XLSX = require('/tmp/xlsx-parse/node_modules/xlsx');
}
const fs = require('fs');

const xlsxPath = '/tmp/bosarsa2.xlsx';
console.log('Reading Excel:', xlsxPath);
const wb = XLSX.readFile(xlsxPath);

// Repeater columns (same as import script)
const REP_COLS = {
  15: 'Gerlitzen 2m',
  16: 'Gerlitzen 70cm',
  17: 'Magdalensberg linked',
  18: 'Buschberg 70cm',
  19: 'Direkte 145.300',
  20: 'Goldeck 2m',
  21: 'Dobratsch 23cm',
  22: 'Struška 70cm',
  23: 'Hochstuhl 70cm',
  24: 'Zirbitzkogel 70cm',
  25: 'Direkte 145.525',
};

for (const sheetName of wb.SheetNames) {
  if (!sheetName.match(/^\d{8}$/)) continue;

  const dateStr = sheetName.replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3');
  const ws = wb.Sheets[sheetName];
  const data = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

  let totalCells = 0;
  let nonEmptyCells = 0;
  let callsigns = [];
  let reportCells = []; // All non-empty report cells with their content

  // Rows: skip header (row 0), data starts at row 1
  // Last rows are summary rows (Summe, TN, etc.)
  for (let rowIdx = 1; rowIdx < data.length; rowIdx++) {
    const row = data[rowIdx];
    const callsign = String(row[0] || '').trim().toUpperCase();

    // Skip empty rows and summary rows
    if (!callsign || callsign === 'SUMME' || callsign === 'TN' || callsign === 'ANZAHL'
        || callsign.match(/^SUMME/i) || callsign.match(/^ANZAHL/i)
        || callsign.match(/^\d+$/) || callsign === 'GESAMT') continue;

    // Check if this looks like a callsign (has letters and possibly numbers)
    if (!callsign.match(/[A-Z]/)) continue;

    callsigns.push(callsign);

    // Check all repeater columns
    for (const [colStr, repName] of Object.entries(REP_COLS)) {
      const col = parseInt(colStr);
      const cellVal = row[col];
      if (cellVal === undefined || cellVal === null || cellVal === '' || cellVal === 0) continue;

      const val = String(cellVal).trim();
      if (!val || val === '0') continue;

      totalCells++;

      // Count individual reports in multi-report cells
      const parts = val.split(/,\s*(?=\d|OP)/i);
      nonEmptyCells += parts.length;

      reportCells.push({
        callsign,
        row: rowIdx + 1,
        col,
        repName,
        value: val,
        parts: parts.length,
      });
    }
  }

  console.log(`\n=== ${dateStr} (Sheet: ${sheetName}) ===`);
  console.log(`Zeilen mit Rufzeichen: ${callsigns.length}`);
  console.log(`Nicht-leere Rapport-Zellen: ${totalCells}`);
  console.log(`Einzelne Rapporte (nach Split): ${nonEmptyCells}`);

  // Show per-repeater breakdown
  const perRep = {};
  for (const rc of reportCells) {
    if (!perRep[rc.repName]) perRep[rc.repName] = { cells: 0, reports: 0 };
    perRep[rc.repName].cells++;
    perRep[rc.repName].reports += rc.parts;
  }
  console.log('Per Umsetzer:');
  for (const [name, counts] of Object.entries(perRep)) {
    console.log(`  ${name}: ${counts.cells} Zellen, ${counts.reports} Rapporte`);
  }

  // Show multi-report cells
  const multiCells = reportCells.filter(rc => rc.parts > 1);
  if (multiCells.length > 0) {
    console.log(`Multi-Zellen (${multiCells.length}):`);
    multiCells.forEach(mc => console.log(`  ${mc.callsign} @ ${mc.repName}: "${mc.value}" (${mc.parts} Teile)`));
  }
}

console.log('\n\n=== GESAMTÜBERSICHT ===');
// Recount totals
let grandCells = 0, grandReports = 0, grandAttendees = 0;
for (const sheetName of wb.SheetNames) {
  if (!sheetName.match(/^\d{8}$/)) continue;
  const dateStr = sheetName.replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3');
  const ws = wb.Sheets[sheetName];
  const data = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

  let sheetAttendees = 0, sheetReports = 0;
  for (let rowIdx = 1; rowIdx < data.length; rowIdx++) {
    const row = data[rowIdx];
    const callsign = String(row[0] || '').trim().toUpperCase();
    if (!callsign || !callsign.match(/[A-Z]/) || callsign.match(/^(SUMME|TN|ANZAHL|GESAMT)/i) || callsign.match(/^\d+$/)) continue;

    let hasReport = false;
    for (const colStr of Object.keys(REP_COLS)) {
      const col = parseInt(colStr);
      const val = String(row[col] || '').trim();
      if (!val || val === '0') continue;
      hasReport = true;
      const parts = val.split(/,\s*(?=\d|OP)/i);
      sheetReports += parts.length;
    }
    if (hasReport) sheetAttendees++;
  }
  grandAttendees += sheetAttendees;
  grandReports += sheetReports;
  console.log(`${dateStr}: ${sheetAttendees} Teilnehmer, ${sheetReports} Rapporte`);
}
console.log(`TOTAL: ${grandAttendees} Teilnehmer, ${grandReports} Rapporte`);

