const REP_COLS = {
  15: 'Gerlitzen 2m',
  16: 'Gerlitzen 70cm',
  17: 'Magdalensberg linked',
  18: 'Buschberg 70cm',
  19: 'Direkte 145.300',
  20: 'Goldeck 2m',
  21: 'Dobratsch 23cm',
  22: 'Struška 70cm',
  23: 'Hochstuhl 70cm',
  24: 'Zirbitzkogel 70cm',
  25: 'Direkte 145.525',
};

// Read DB import JSON for comparison
const fs = require('fs');
const importData = JSON.parse(fs.readFileSync('/tmp/bosarsa-import.json', 'utf-8'));
const jsonByDate = {};
for (const ex of importData.exercises) {
  jsonByDate[ex.date] = ex;
}

console.log('=== EXCEL ↔ JSON ↔ DB Vergleich ===\n');

let totalExcelCells = 0, totalJsonReports = 0;
let allMissing = [];

for (const sheetName of wb.SheetNames) {
  if (!sheetName.match(/^\d{8}$/)) continue;
  const dateStr = sheetName.replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3');
  const ws = wb.Sheets[sheetName];
  const data = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

  const jsonEx = jsonByDate[dateStr];
  const jsonReportSet = new Set();
  if (jsonEx) {
    for (const r of jsonEx.reports) {
      jsonReportSet.add(r.callsign + '|' + r.repeaterId + '|' + r.original);
    }
  }

  let excelCells = 0;
  let missing = [];

  for (let rowIdx = 1; rowIdx < data.length; rowIdx++) {
    const row = data[rowIdx];
    const callsign = String(row[0] || '').trim().toUpperCase();
    if (!callsign || !callsign.match(/[A-Z]/) || callsign.match(/^(SUMME|TN|ANZAHL|GESAMT)/i) || callsign.match(/^\d+$/)) continue;

    for (const [colStr, repName] of Object.entries(REP_COLS)) {
      const col = parseInt(colStr);
      const val = String(row[col] || '').trim();
      if (!val || val === '0') continue;

      excelCells++;

      // Check if this cell's content was captured in JSON
      // The parser splits multi-cells, so check each part
      const parts = val.split(/,\s*(?=\d|OP)/i);
      for (const part of parts) {
        const trimmed = part.trim();
        // Search in JSON reports for this callsign + repeater + original text
        const found = jsonEx && jsonEx.reports.find(r =>
          r.callsign === callsign && r.original === trimmed
        );
        if (!found) {
          // Maybe the original was normalized differently - check by callsign + repeater col
          const altFound = jsonEx && jsonEx.reports.find(r =>
            r.callsign === callsign && r.repeaterName === repName &&
            (r.original === trimmed || r.original.includes(trimmed) || trimmed.includes(r.original))
          );
          if (!altFound) {
            missing.push({
              callsign,
              row: rowIdx + 1,
              col,
              repName,
              value: trimmed,
              fullCell: val,
            });
          }
        }
      }
    }
  }

  totalExcelCells += excelCells;
  totalJsonReports += (jsonEx ? jsonEx.reports.length : 0);

  if (missing.length > 0) {
    console.log(`${dateStr}: ${missing.length} Excel-Einträge NICHT im JSON:`);
    for (const m of missing) {
      console.log(`  Zeile ${m.row} | ${m.callsign} @ ${m.repName} (Spalte ${m.col}): "${m.value}" [Zelle: "${m.fullCell}"]`);
    }
    allMissing.push(...missing);
  } else {
    console.log(`${dateStr}: OK — alle ${excelCells} Zellen im JSON`);
  }
}

console.log(`\n--- ERGEBNIS ---`);
console.log(`Excel-Zellen total: ${totalExcelCells}`);
console.log(`JSON-Rapporte total: ${totalJsonReports}`);
console.log(`Fehlende Einträge: ${allMissing.length}`);
if (allMissing.length > 0) {
  console.log('\nAlle fehlenden:');
  allMissing.forEach(m => console.log(`  ${m.callsign} @ ${m.repName}: "${m.value}"`));
}

