function httpsGet(url) {
  return new Promise((resolve, reject) => {
    https.get(url, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => resolve(body));
    }).on('error', reject);
  });
}

async function getSessionKey() {
  const url = `https://xmldata.qrz.com/xml/current/?username=${encodeURIComponent(QRZ_USER)}&password=${encodeURIComponent(QRZ_PW)}`;
  const xml = await httpsGet(url);
  const keyMatch = xml.match(/<Key>([^<]+)<\/Key>/);
  if (!keyMatch) {
    console.error('Login failed:', xml);
    process.exit(1);
  }
  return keyMatch[1];
}

function parseCallsign(xml) {
  const get = (tag) => {
    const m = xml.match(new RegExp(`<${tag}>([^<]*)</${tag}>`));
    return m ? m[1] : null;
  };
  return {
    callsign: get('call'),
    fname: get('fname'),
    name: get('name'),
    addr1: get('addr1'),
    addr2: get('addr2'),
    country: get('country'),
    qth: get('addr2') || get('addr1'),
  };
}

async function lookupCallsign(sessionKey, callsign) {
  const url = `https://xmldata.qrz.com/xml/current/?s=${sessionKey}&callsign=${encodeURIComponent(callsign)}`;
  const xml = await httpsGet(url);
  if (xml.includes('<Error>')) {
    const err = xml.match(/<Error>([^<]+)<\/Error>/);
    return { callsign, error: err ? err[1] : 'unknown error' };
  }
  return parseCallsign(xml);
}

