  'OE1CPT','OE1EBG','OE1MIA','OE1SIB','OE1VRS','OE1YAS',
  'OE2CKF','OE2CRP','OE2GUN','OE2SAO',
  'OE3DJE','OE3EAR','OE3HIP','OE3HRX','OE3KNS','OE3NHA','OE3POC','OE3PWR','OE3SSV','OE3TWH','OE3XRC',
  'OE4ETN','OE4JAR','OE4PAO',
  'OE5CSL','OE5FIL','OE5HDN','OE5MCM','OE5ODR','OE5XBA',
  'OE6AAD','OE6DJG','OE6DVM','OE6KPE','OE6MRF','OE6TAR','OE6TNO','OE6XMT',
  'OE7NCC','OE7NLY','OE7RTM',
  'OE8DDG','OE8HAM','OE8HXK','OE8IHT','OE8ROG','OE8SRM','OE8SSX','OE8TIK','OE8TJT','OE8VIK','OE8WBG','OE8YYY',
  'OE9OMV','OE9TBI',
  'S56DN',
];

async function main() {
  console.log('Logging into QRZ.com...');
  const sessionKey = await getSessionKey();
  console.log('Session key obtained.\n');

  const results = [];
  for (const cs of callsigns) {
    const result = await lookupCallsign(sessionKey, cs);
    if (result.error) {
      console.log(`  ${cs}: ERROR — ${result.error}`);
    } else {
      const fullName = [result.fname, result.name].filter(Boolean).join(' ');
      console.log(`  ${cs}: ${fullName} | ${result.qth || '—'} | ${result.country || '—'}`);
    }
    results.push(result);
    // Small delay to be polite
    await new Promise(r => setTimeout(r, 200));
