const fs = require('fs');
const results = JSON.parse(fs.readFileSync('/tmp/qrz-results.json', 'utf-8'));

// Build SQL update statements
const updates = [];
for (const r of results) {
  if (r.error) continue;
  const fullName = [r.fname, r.name].filter(Boolean).join(' ').trim();
  const qth = r.qth || null;
  if (fullName || qth) {
    updates.push({ callsign: r.callsign, name: fullName || null, qth });
  }
}

console.log('Updates to apply:', updates.length);
updates.forEach(u => console.log(`  ${u.callsign}: "${u.name}" | "${u.qth}"`));

// Write as a script to run in Docker
const lines = [
  "const Database = require('/app/node_modules/better-sqlite3');",
  "const db = new Database('/data/bosarsalog.db');",
  "db.pragma('journal_mode = WAL');",
  "",
  "const PREFIX_MAP = [",
  "  [/^OE1/, '01'], [/^OE2/, '02'], [/^OE3/, '03'], [/^OE4/, '04'], [/^OE5/, '05'],",
  "  [/^OE6/, '06'], [/^OE7/, '07'], [/^OE8/, '08'], [/^OE9/, '09'],",
  "];",
  "function toBlCode(cs) {",
  "  for (const [re, code] of PREFIX_MAP) { if (re.test(cs)) return code; }",
  "  return null;",
  "}",
  "",
  "const update = db.prepare('UPDATE operators SET name = ?, qth = ?, bundesland_code = COALESCE(bundesland_code, ?) WHERE callsign = ?');",
  "",
  "const updates = " + JSON.stringify(updates) + ";",
  "",
  "let updated = 0;",
  "const tx = db.transaction(() => {",
  "  for (const u of updates) {",
  "    const bl = toBlCode(u.callsign);",
  "    const result = update.run(u.name, u.qth, bl, u.callsign);",
  "    if (result.changes > 0) {",
  "      console.log('  Updated: ' + u.callsign + ' → ' + u.name + ' | ' + u.qth);",
  "      updated++;",
  "    } else {",
  "      console.log('  NOT FOUND in DB: ' + u.callsign);",
  "    }",
  "  }",
  "});",
  "tx();",
  "",
  "console.log('\\nUpdated: ' + updated);",
  "",
  "// Show remaining without name",
  "const still = db.prepare(\"SELECT o.callsign, COUNT(sr.id) as cnt FROM operators o JOIN signal_reports sr ON sr.operator_id = o.id WHERE o.name IS NULL OR o.name = '' GROUP BY o.id ORDER BY o.callsign\").all();",
  "console.log('\\nNoch ohne Name (' + still.length + '):');",
  "still.forEach(s => console.log('  ' + s.callsign + ' (' + s.cnt + ' Rapporte)'));",
  "",
  "db.close();",
];

fs.writeFileSync('/tmp/apply-qrz-updates.cjs', lines.join('\n'));
console.log('\nScript written to /tmp/apply-qrz-updates.cjs');

