  // Clean name: remove callsign from name (e.g. "Horst OE8HXK")
  if (fullName) fullName = fullName.replace(/\s*OE\d\w+/g, '').trim();
  // Clean name: remove trailing dots (e.g. "Helmuth .")
  if (fullName) fullName = fullName.replace(/\s*\.\s*$/, '').trim();
  // Clean name: remove "( MARK )" style nicknames
  if (fullName) fullName = fullName.replace(/\s*\([^)]+\)\s*/g, ' ').trim();
  // Clean QTH: "null" string → null
  if (qth === 'null') qth = null;
  // Clean QTH: remove pipe-separated extra info (e.g. "VILLACH | CARINTHIA | AUSTRIA | EUROPE")
  if (qth && qth.includes('|')) qth = qth.split('|')[0].trim();
  // Clean QTH: "Austria" alone isn't useful
  if (qth === 'Austria') qth = null;
  // Clean QTH: remove leading postal code for Austrian locations
  // Keep it actually - it's useful info
  // Clean QTH: "Vienna" → "Wien"
  if (qth === 'Vienna') qth = 'Wien';

  if (fullName || qth) {
    updates.push({ callsign: originalCs, name: fullName || null, qth });
  }
}

