let XLSX;
try { XLSX = require('xlsx'); } catch (e) {
  XLSX = require('/tmp/xlsx-parse/node_modules/xlsx');
}
const fs = require('fs');

const wb = XLSX.readFile('/tmp/bosarsa2.xlsx');
const importData = JSON.parse(fs.readFileSync('/tmp/bosarsa-import.json', 'utf-8'));
const qrzResults = JSON.parse(fs.readFileSync('/tmp/qrz-results.json', 'utf-8'));

// Original callsigns queried on QRZ
const qrzQueried = [
  'DG4CG','DG4CK','DK5LL','DK7CK','DL1MNG','DM5CQ','DN9AZ','DN9GH',
  'DO1FMI','DO3AJ','DO8KR','HB9ILD',
  'OE1CPT','OE1EBG','OE1MIA','OE1SIB','OE1VRS','OE1YAS',
  'OE2CKF','OE2CRP','OE2GUN','OE2SAO',
  'OE3DJE','OE3EAR','OE3HIP','OE3HRX','OE3KNS','OE3NHA','OE3POC','OE3PWR','OE3SSV','OE3TWH','OE3XRC',
  'OE4ETN','OE4JAR','OE4PAO',
  'OE5CSL','OE5FIL','OE5HDN','OE5MCM','OE5ODR','OE5XBA',
  'OE6AAD','OE6DJG','OE6DVM','OE6KPE','OE6MRF','OE6TAR','OE6TNO','OE6XMT',
  'OE7NCC','OE7NLY','OE7RTM',
  'OE8DDG','OE8HAM','OE8HXK','OE8IHT','OE8ROG','OE8SRM','OE8SSX','OE8TIK','OE8TJT','OE8VIK','OE8WBG','OE8YYY',
  'OE9OMV','OE9TBI',
  'S56DN',
];

const REP_COLS = {
  15: 'Gerlitzen 2m', 16: 'Gerlitzen 70cm', 17: 'Magdalensberg linked',
  18: 'Buschberg 70cm', 19: 'Direkte 145.300', 20: 'Goldeck 2m',
  21: 'Dobratsch 23cm', 22: 'Struška 70cm', 23: 'Hochstuhl 70cm',
  24: 'Zirbitzkogel 70cm', 25: 'Direkte 145.525',
};

const EP_MAP = {
  49: 'HK (Hermannskogel)', 50: 'GB (Gaisberg)', 51: 'NBST (Nebelstein)',
  52: 'JAU (Jauerling)', 53: 'FK (Feuerkogel)', 54: 'SCHÖ (Schöckl)',
  55: 'LT (Lachtal)', 56: 'Telfs', 57: 'Hochstein', 58: 'Ahorn',
  59: 'MK (Magdalensberg)', 60: 'DO (Dornbirn)', 61: 'BR (Brentenriegel)',
  62: 'PATSCH (Patscherkofel)',
};

const lines = [];
const w = (s) => lines.push(s);

w('# Excel-Import Bericht — BOS-ARSA Krisenkommunikationsübung');
w('');
w('**Datum:** 2026-02-17');
w('**Quelle:** `2026 BOS-ARSA - Krisenkommunikationsübung (1).xlsx`');
w('**Importiert durch:** `scripts/parse-excel-to-json.cjs` → `scripts/import-json-to-db.cjs`');
w('');
w('---');
w('');
w('## 1. Zusammenfassung');
w('');

let totalExcelCells = 0, totalExcelReports = 0, totalAttendees = 0;
const exerciseSummary = [];

for (const ex of importData.exercises) {
  const sheetName = ex.sheetName;
  const ws = wb.Sheets[sheetName];
  const data = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

  let excelCells = 0, excelReports = 0, attendees = 0;
  for (let rowIdx = 1; rowIdx < data.length; rowIdx++) {
    const row = data[rowIdx];
    const cs = String(row[0] || '').trim().toUpperCase();
    if (!cs || !cs.match(/[A-Z]/) || cs.match(/^(SUMME|TN|ANZAHL|GESAMT)/i) || cs.match(/^\d+$/)) continue;
    let hasReport = false;
    for (const colStr of Object.keys(REP_COLS)) {
      const val = String(row[parseInt(colStr)] || '').trim();
      if (!val || val === '0') continue;
      hasReport = true;
      excelCells++;
      excelReports += val.split(/,\s*(?=\d|OP)/i).length;
    }
    if (hasReport) attendees++;
  }

  totalExcelCells += excelCells;
  totalExcelReports += excelReports;
  totalAttendees += attendees;

  // Count multi-cells and OP markers from JSON
  const multiCells = [];
  const grouped = {};
  for (const r of ex.reports) {
    const key = r.callsign + '|' + r.repeaterId;
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(r);
  }
  let mergedCount = 0;
  for (const [k, v] of Object.entries(grouped)) {
    if (v.length > 1) mergedCount += v.length - 1;
  }

  const opMarkers = ex.reports.filter(r => r.isOp && !r.readability).length;

  exerciseSummary.push({
    date: ex.date,
    attendees,
    excelCells,
    excelReports,
    jsonReports: ex.reports.length,
    opMarkers,
    merged: mergedCount,
    dbExpected: ex.reports.length - mergedCount,
  });
}

w('| | Wert |');
w('|---|---|');
w('| Übungen importiert | 7 |');
w(`| Zeitraum | 2026-01-04 bis 2026-02-15 |`);
w(`| Excel-Zellen (nicht leer) | ${totalExcelCells} |`);
w(`| Einzelrapporte (nach Multi-Split) | ${totalExcelReports} |`);
w(`| Teilnehmer (über alle Übungen, mit Duplikaten) | ${totalAttendees} |`);
w(`| Eindeutige Operatoren aus Import | 152 (neu angelegt) |`);
w(`| Nicht geparste Zellen | 1 ("pc" von OE6TSF) |`);
w('');

w('## 2. Import pro Übung');
w('');
w('| Datum | Teilnehmer | Excel-Zellen | Rapporte (geparst) | OP-Marker | Multi-EP merged | DB-Einträge |');
w('|-------|------------|-------------|-------------------|-----------|----------------|-------------|');
for (const s of exerciseSummary) {
  w(`| ${s.date} | ${s.attendees} | ${s.excelCells} | ${s.jsonReports} | ${s.opMarkers} | ${s.merged} | ${s.dbExpected} |`);
}
const totalJson = exerciseSummary.reduce((a, s) => a + s.jsonReports, 0);
const totalMerged = exerciseSummary.reduce((a, s) => a + s.merged, 0);
const totalDb = exerciseSummary.reduce((a, s) => a + s.dbExpected, 0);
const totalOp = exerciseSummary.reduce((a, s) => a + s.opMarkers, 0);
w(`| **Gesamt** | **${totalAttendees}** | **${totalExcelCells}** | **${totalJson}** | **${totalOp}** | **${totalMerged}** | **${totalDb}** |`);
w('');

w('**Erklärung Multi-EP merged:** Wenn ein Operator in einer Zelle mehrere Einstiegspunkte hatte');
w('(z.B. "5/9 FK, 5/9 GB"), wurde der erste als Haupteintrag gespeichert und die weiteren im `notes`-Feld.');
