w('# Excel-Import Bericht — BOS-ARSA Krisenkommunikationsübung');
w('');
w('**Datum:** 2026-02-17');
w('**Quelle:** `2026 BOS-ARSA - Krisenkommunikationsübung (1).xlsx`');
w('**Importiert durch:** `scripts/parse-excel-to-json.cjs` → `scripts/import-json-to-db.cjs`');
w('');
w('---');
w('');
w('## 1. Zusammenfassung');
w('');

let totalExcelCells = 0, totalExcelReports = 0, totalAttendees = 0;
const exerciseSummary = [];

for (const ex of importData.exercises) {
  const sheetName = ex.sheetName;
  const ws = wb.Sheets[sheetName];
  const data = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });

  let excelCells = 0, excelReports = 0, attendees = 0;
  for (let rowIdx = 1; rowIdx < data.length; rowIdx++) {
    const row = data[rowIdx];
    const cs = String(row[0] || '').trim().toUpperCase();
    if (!cs || !cs.match(/[A-Z]/) || cs.match(/^(SUMME|TN|ANZAHL|GESAMT)/i) || cs.match(/^\d+$/)) continue;
    let hasReport = false;
    for (const colStr of Object.keys(REP_COLS)) {
      const val = String(row[parseInt(colStr)] || '').trim();
      if (!val || val === '0') continue;
      hasReport = true;
      excelCells++;
      excelReports += val.split(/,\s*(?=\d|OP)/i).length;
    }
    if (hasReport) attendees++;
  }

  totalExcelCells += excelCells;
  totalExcelReports += excelReports;
  totalAttendees += attendees;

