const totalMerged = exerciseSummary.reduce((a, s) => a + s.merged, 0);
const totalDb = exerciseSummary.reduce((a, s) => a + s.dbExpected, 0);
const totalOp = exerciseSummary.reduce((a, s) => a + s.opMarkers, 0);
w(`| **Gesamt** | **${totalAttendees}** | **${totalExcelCells}** | **${totalJson}** | **${totalOp}** | **${totalMerged}** | **${totalDb}** |`);
w('');

w('**Erklärung Multi-EP merged:** Wenn ein Operator in einer Zelle mehrere Einstiegspunkte hatte');
w('(z.B. "5/9 FK, 5/9 GB"), wurde der erste als Haupteintrag gespeichert und die weiteren im `notes`-Feld.');
w('');

w('## 3. Umsetzer-Zuordnung');
w('');
w('Die Excel-Datei verwendet 11 Spalten (P–Z) für Umsetzer:');
w('');
w('| Excel-Spalte | Umsetzer | DB-ID | Typ |');
w('|-------------|----------|-------|-----|');
for (const [col, name] of Object.entries(REP_COLS)) {
