  w(`| ${String.fromCharCode(64 + parseInt(col))} (${col}) | ${name} | siehe DB | ${isLinked ? 'Linked (OE-Link)' : 'Einzeln'} |`);
}
w('');

w('### OE-Link Einstiegspunkte (Magdalensberg linked)');
w('');
w('Rapporte für den verlinkten Umsetzer Magdalensberg wurden anhand des EP-Suffix');
w('(z.B. "5/9+30 **HK**") auf die jeweiligen verlinkten Repeater umgemappt:');
w('');
w('| Abkürzung | Standort | Rufzeichen | BL | Verlinkt mit Repeater |');
w('|-----------|----------|------------|----|-----------------------|');
w('| HK | Hermannskogel | OE1XAT | OE1 | Hermannskogel 70cm |');
w('| GB | Gaisberg | OE2XZR | OE2 | Gaisberg 70cm |');
w('| NBST | Nebelstein | OE3XNR | OE3 | Nebelstein 70cm |');
w('| JAU | Jauerling | OE3XWJ | OE3 | Jauerling 70cm |');
w('| BR | Brentenriegel | OE4XUB | OE4 | Brentenriegel 70cm * |');
w('| FK | Feuerkogel | OE5XFK | OE5 | Feuerkogel 70cm |');
