    const row = data[rowIdx];
    const cs = String(row[0] || '').trim().toUpperCase();
    if (!cs || !cs.match(/[A-Z]/) || cs.match(/^(SUMME|TN|ANZAHL|GESAMT)/i) || cs.match(/^\d+$/)) continue;
    let hasReport = false;
    for (const colStr of Object.keys(REP_COLS)) {
      const val = String(row[parseInt(colStr)] || '').trim();
      if (!val || val === '0') continue;
      hasReport = true;
      excelCells++;
      excelReports += val.split(/,\s*(?=\d|OP)/i).length;
    }
    if (hasReport) attendees++;
  }

  totalExcelCells += excelCells;
  totalExcelReports += excelReports;
  totalAttendees += attendees;

  // Count multi-cells and OP markers from JSON
  const multiCells = [];
  const grouped = {};
  for (const r of ex.reports) {
    const key = r.callsign + '|' + r.repeaterId;
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(r);
  }
  let mergedCount = 0;
  for (const [k, v] of Object.entries(grouped)) {
    if (v.length > 1) mergedCount += v.length - 1;
  }

  const opMarkers = ex.reports.filter(r => r.isOp && !r.readability).length;

  exerciseSummary.push({
    date: ex.date,
    attendees,
    excelCells,
    excelReports,
    jsonReports: ex.reports.length,
    opMarkers,
    merged: mergedCount,
    dbExpected: ex.reports.length - mergedCount,
  });
}

