  'OE9OMV','OE9TBI',
  'S56DN',
];

const REP_COLS = {
  15: 'Gerlitzen 2m', 16: 'Gerlitzen 70cm', 17: 'Magdalensberg linked',
  18: 'Buschberg 70cm', 19: 'Direkte 145.300', 20: 'Goldeck 2m',
  21: 'Dobratsch 23cm', 22: 'Struška 70cm', 23: 'Hochstuhl 70cm',
