w('| Excel-Spalte | Umsetzer | DB-ID | Typ |');
w('|-------------|----------|-------|-----|');
for (const [col, name] of Object.entries(REP_COLS)) {
  const isLinked = name === 'Magdalensberg linked';
  w(`| ${String.fromCharCode(64 + parseInt(col))} (${col}) | ${name} | siehe DB | ${isLinked ? 'Linked (OE-Link)' : 'Einzeln'} |`);
}
w('');

w('### OE-Link Einstiegspunkte (Magdalensberg linked)');
w('');
w('Rapporte für den verlinkten Umsetzer Magdalensberg wurden anhand des EP-Suffix');
w('(z.B. "5/9+30 **HK**") auf die jeweiligen verlinkten Repeater umgemappt:');
w('');
w('| Abkürzung | Standort | Rufzeichen | BL | Verlinkt mit Repeater |');
w('|-----------|----------|------------|----|-----------------------|');
w('| HK | Hermannskogel | OE1XAT | OE1 | Hermannskogel 70cm |');
w('| GB | Gaisberg | OE2XZR | OE2 | Gaisberg 70cm |');
w('| NBST | Nebelstein | OE3XNR | OE3 | Nebelstein 70cm |');
w('| JAU | Jauerling | OE3XWJ | OE3 | Jauerling 70cm |');
w('| BR | Brentenriegel | OE4XUB | OE4 | Brentenriegel 70cm * |');
w('| FK | Feuerkogel | OE5XFK | OE5 | Feuerkogel 70cm |');
w('| SCHÖ | Schöckl | OE6XAG | OE6 | Schöckl 2m |');
w('| LT | Lachtal | OE6XDG | OE6 | Lachtal 2m |');
w('| Hochstein | Hochstein | OE7XLI | OE7 | Hochstein 70cm |');
w('| Ahorn | Ahorn | OE7XZT | OE7 | Ahorn 70cm |');
w('| PATSCH | Patscherkofel | OE7XBI | OE7 | Patscherkofel 70cm * |');
w('| MK/MGDB | Magdalensberg | OE8XMK | OE8 | Magdalensberg linked |');
w('| DO | Dornbirn | OE9XXD | OE9 | Dornbirn 70cm |');
w('');
w('\\* = Repeater-Eintrag wurde beim Import neu angelegt');
w('');

w('### Weitere EP-Abkürzungen im Excel');
w('');
w('| Abkürzung | Aufgelöst zu |');
w('|-----------|-------------|');
w('| 3xwj | JAU (OE3XWJ = Jauerling) |');
w('| 2xzr | GB (OE2XZR = Gaisberg) |');
w('| Magdalensberg | MK |');
w('| BrR | BR (Brentenriegel) |');
w('| PaK, PK | PATSCH (Patscherkofel) |');
w('| HOCHS | Hochstein |');
w('| Jau, jau | JAU |');
